const res = await tool.fetch_url({ url: "https://www.theory.com/sitemap_1.xml" });
const xml = res.body;
const dressUrls = [];
const matches = xml.matchAll(/<loc>(https:\/\/www\.theory\.com\/[^<]*dress[^<]*)<\/loc>/gi);
for (const m of matches) {
  dressUrls.push(m[1]);
}
console.log(`Found ${dressUrls.length} dress URLs:`);
console.log(dressUrls.filter(u => u.includes('green') || u.includes('crepe') || u.includes('slip') || u.includes('satin') || u.includes('evening') || u.includes('maxi') || u.includes('midi')).slice(0, 20));

