const urls = [
  "https://www.ooshirts.com/services/dtg-print",
  "https://www.ooshirts.com/services/no-minimum-digital-printing",
  "https://www.ooshirts.com/services/full-color-digital-printing"
];

for (const u of urls) {
  try {
    const res = await tool.fetch_url({ url: u });
    console.log(u, "status:", res.status);
    if (res.status === 200) {
      console.log(res.body.slice(0, 300));
    }
  } catch (e) {
    console.log(u, "error:", e.message);
  }
}

